(5252291, 764621, 93777, '<td valign="top">Love the soft lighting on the flowers but I wish it was just a tad brighter especially on and around the apples.</td>', 'Love the soft lighting on the flowers but I wish it was just a tad brighter especially on and around the apples.', '2009-02-11 22:43:05.000000', NULL, 1),
(5252293, 764639, 83313, '<td valign="top">If you will now step out of the tour bus, we will continue our guided tour of the internet with a stop at DPChallenge.com. Over here you will see the currently running apple challenge, where they have used incredible amounts of water drops. We are installing larger interwebitubes here soon that should be able to handle all the drainage. A new treatment plant is to be built in 2012. Be careful, you can drown in this place.<br/> <br/>Oh, and nicely done. Hope you have a sense of humor.</td>', 'If you will now step out of the tour bus, we will continue our guided tour of the internet with a stop at DPChallenge.com. Over here you will see the currently running apple challenge, where they have used incredible amounts of water drops. We are installing larger interwebitubes here soon that should be able to handle all the drainage. A new treatment plant is to be built in 2012. Be careful, you can drown in this place. Oh, and nicely done. Hope you have a sense of humor.', '2009-02-11 22:43:39.000000', NULL, 1),
(5252299, 764416, 83313, '<td valign="top">He needs a spotter, or he''ll be sauce.</td>', 'He needs a spotter, or he''ll be sauce.', '2009-02-11 22:44:42.000000', NULL, 1),
