(5260529, 763087, 52500, '<td valign="top">Good idea, horrible execution.  If this was a legitimate effort at making a good photo, I recommend that you check out the tutorials section of the site to get started on making better photos.  Plus, the size alone on this entry is enough to send it down to a 2 for me.</td>', 'Good idea, horrible execution.  If this was a legitimate effort at making a good photo, I recommend that you check out the tutorials section of the site to get started on making better photos.  Plus, the size alone on this entry is enough to send it down to a 2 for me.', '2009-02-17 13:04:01.000000', NULL, 1),
(5260530, 763164, 52500, '<td valign="top">Alas, the link is so tenuous that I can''t find it.</td>', 'Alas, the link is so tenuous that I can''t find it.', '2009-02-17 13:04:04.000000', NULL, 1),
(5260535, 764487, 52500, '<td valign="top">I can see where you were going with this, but you just didn''t get there.  A still life is a good idea, but random lettuce and such tossed onto a bumpy piece of red felt with harsh lighting isn''t very appealing.</td>', 'I can see where you were going with this, but you just didn''t get there.  A still life is a good idea, but random lettuce and such tossed onto a bumpy piece of red felt with harsh lighting isn''t very appealing.', '2009-02-17 13:06:25.000000', NULL, 1),
(5260537, 763578, 52500, '<td valign="top">The image itself isn''t too bad, but at 500x500 the best I can give you is a 3.  Probably would have been a 5 at full size.</td>', 'The image itself isn''t too bad, but at 500x500 the best I can give you is a 3.  Probably would have been a 5 at full size.', '2009-02-17 13:07:34.000000', NULL, 1),
(5260540, 762877, 52500, '<td valign="top">Not a bad image, I like the high contrast and lighting, but at 500px on the long edge I can''t go higher than a 3.</td>', 'Not a bad image, I like the high contrast and lighting, but at 500px on the long edge I can''t go higher than a 3.', '2009-02-17 13:08:40.000000', NULL, 1),
(5260543, 764016, 52500, '<td valign="top">Red and green can be complimentary colors, but it doesn''t work here.  The light is just too harsh and nothing''s really in focus.  For shots of food to work the viewer needs to be able to imagine eating the food, and here the apple looks like it''s sitting in the bottom of on old hollowed out lettuce.  Very unappetizing.</td>', 'Red and green can be complimentary colors, but it doesn''t work here.  The light is just too harsh and nothing''s really in focus.  For shots of food to work the viewer needs to be able to imagine eating the food, and here the apple looks like it''s sitting in the bottom of on old hollowed out lettuce.  Very unappetizing.', '2009-02-17 13:11:34.000000', NULL, 1),
(5260544, 764386, 52500, '<td valign="top">This is funny in a really stupid, really bad photo kind of way, but that only gets it up to a 3 for me.</td>', 'This is funny in a really stupid, really bad photo kind of way, but that only gets it up to a 3 for me.', '2009-02-17 13:12:45.000000', NULL, 1),
(5260545, 763641, 52500, '<td valign="top">The color simply doesn''t work for me at all.  For some reason it makes me think she is diseased.  With a different color treatment this could have been an average image.</td>', 'The color simply doesn''t work for me at all.  For some reason it makes me think she is diseased.  With a different color treatment this could have been an average image.', '2009-02-17 13:15:04.000000', NULL, 1),
(5260552, 764023, 52500, '<td valign="top">It''s a decent idea, only a little overdone.  Not great technically, but the big killer is the size.</td>', 'It''s a decent idea, only a little overdone.  Not great technically, but the big killer is the size.', '2009-02-17 13:22:14.000000', NULL, 1),
(5260553, 763999, 52500, '<td valign="top">I like the way you filled the frame, but that''s about it.  It seems really low on contrast, the apple isn''t in focus, and I hate religious references.</td>', 'I like the way you filled the frame, but that''s about it.  It seems really low on contrast, the apple isn''t in focus, and I hate religious references.', '2009-02-17 13:23:32.000000', NULL, 1),
(5260554, 764243, 52500, '<td valign="top">Obviously not a very original idea, and the execution is worse than the rest.  Nothing seems to be in focus, the white balance appears to be off, and there is purple fringing everywhere.</td>', 'Obviously not a very original idea, and the execution is worse than the rest.  Nothing seems to be in focus, the white balance appears to be off, and there is purple fringing everywhere.', '2009-02-17 13:25:38.000000', NULL, 1),
(5260557, 764199, 52500, '<td valign="top">A decent image, but you get a 3 from me for the size.  640 is annoyingly small enough.  Also, if you sharpen before you add the border you won''t get that 1 pixel lighter edge on your image.</td>', 'A decent image, but you get a 3 from me for the size.  640 is annoyingly small enough.  Also, if you sharpen before you add the border you won''t get that 1 pixel lighter edge on your image.', '2009-02-17 13:27:32.000000', NULL, 1),
(5260602, 763679, 98141, '<td valign="top">I like this pic a lot, I enjoy the detail in the water amid the motion blur from the long exposure.</td>', 'I like this pic a lot, I enjoy the detail in the water amid the motion blur from the long exposure.', '2009-02-17 14:02:28.000000', NULL, 1),
(5260604, 764390, 98141, '<td valign="top">Lovely contrast betweet the dark and light, clever idea. Good spotlight trick.</td>', 'Lovely contrast betweet the dark and light, clever idea. Good spotlight trick.', '2009-02-17 14:03:06.000000', NULL, 1),
(5260608, 764221, 98141, '<td valign="top">I like this idea a lot, but I feel that the composition is a little straightforward. Perhaps different cropping would make it pop more? Good, warm tones.</td>', 'I like this idea a lot, but I feel that the composition is a little straightforward. Perhaps different cropping would make it pop more? Good, warm tones.', '2009-02-17 14:04:25.000000', NULL, 1),
(5260610, 764020, 98141, '<td valign="top">I love how rugged that apple looks. Great colors, nice, soft lighting and good composition. This feels classic, reminds me of typical still life oil paintings.</td>', 'I love how rugged that apple looks. Great colors, nice, soft lighting and good composition. This feels classic, reminds me of typical still life oil paintings.', '2009-02-17 14:05:09.000000', NULL, 1),
(5260611, 763653, 98141, '<td valign="top">The lighting is very nice, soft and even. The title and subject are cute. I enjoy the colors and I think that the simple composition works well here. I wish the "bad apple" was a little less scuffed up, I find the natural lines distracting from the marker lines.</td>', 'The lighting is very nice, soft and even. The title and subject are cute. I enjoy the colors and I think that the simple composition works well here. I wish the "bad apple" was a little less scuffed up, I find the natural lines distracting from the marker lines.', '2009-02-17 14:06:44.000000', NULL, 1),
(5260612, 764407, 98141, '<td valign="top">I love this, great texture with the water on the apple and boy do those colors pop! Nice composition too.</td>', 'I love this, great texture with the water on the apple and boy do those colors pop! Nice composition too.', '2009-02-17 14:07:17.000000', NULL, 1),
(5260615, 763580, 98141, '<td valign="top">I like this, good colors. The lighting makes for some really hot spots on those shiny apples though, something a little more diffused might work well?</td>', 'I like this, good colors. The lighting makes for some really hot spots on those shiny apples though, something a little more diffused might work well?', '2009-02-17 14:08:26.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5260617, 764265, 89940, '<td valign="top">Made me LOL.</td>', 'Made me LOL.', '2009-02-17 14:09:18.000000', NULL, 1),
