(5261695, 764524, 81362, '<td valign="top">Would be interested in why you used a shallow depth of field for this.</td>', 'Would be interested in why you used a shallow depth of field for this.', '2009-02-17 23:54:47.000000', NULL, 1),
(5261696, 764398, 81362, '<td valign="top">Might have turned the jug a bit more to remove the white nutritional information part from our field of view.</td>', 'Might have turned the jug a bit more to remove the white nutritional information part from our field of view.', '2009-02-17 23:54:50.000000', NULL, 1),
(5261703, 764393, 81362, '<td valign="top">Juxtaposition of healthy fruit and unhealthy tobacco has potential as a concept. Play of yellow-browns in apples against the similar color in the filter tips is interesting. Execution is weak for several reasons. Textured surface (towel?) distracts the eye. A solid dark surface or metal or reflective surface could dress this up and provide a better contrast to the white tubular paper and the box. Placing the subjects close to the upright background leads to unnecessary angular shadows. Having the second apple, brown cigarette tips, and pack blurred due to shallow depth of field looks accidental. Narrow depth of field (with slower shutter speed and good tripod) might be a better choice.</td>', 'Juxtaposition of healthy fruit and unhealthy tobacco has potential as a concept. Play of yellow-browns in apples against the similar color in the filter tips is interesting. Execution is weak for several reasons. Textured surface (towel?) distracts the eye. A solid dark surface or metal or reflective surface could dress this up and provide a better contrast to the white tubular paper and the box. Placing the subjects close to the upright background leads to unnecessary angular shadows. Having the second apple, brown cigarette tips, and pack blurred due to shallow depth of field looks accidental. Narrow depth of field (with slower shutter speed and good tripod) might be a better choice.', '2009-02-17 23:57:14.000000', NULL, 1),
(5261704, 762877, 81362, '<td valign="top">Might look more delicious with more light, less yellow cast, and sharper focus.</td>', 'Might look more delicious with more light, less yellow cast, and sharper focus.', '2009-02-17 23:57:19.000000', NULL, 1),
(5261705, 764487, 81362, '<td valign="top">Seems to have a yellowish cast. Maybe using a grey card in a test shot would allow correction of white balance in post processing. Might benefit from more careful placement of the various elements of the still life.</td>', 'Seems to have a yellowish cast. Maybe using a grey card in a test shot would allow correction of white balance in post processing. Might benefit from more careful placement of the various elements of the still life.', '2009-02-17 23:57:25.000000', NULL, 1),
