(5262961, 764379, 11467, '<td valign="top">Congratulations to a pretty good score. Scraped in over the 6.0 mark is always good.</td>', 'Congratulations to a pretty good score. Scraped in over the 6.0 mark is always good.', '2009-02-18 11:54:49.000000', NULL, 0),
(5263049, 763478, 43565, '<td valign="top">This is a great idea. Great lighting!</td>', 'This is a great idea. Great lighting!', '2009-02-18 12:57:21.000000', NULL, 0),
(5263080, 764579, 99311, '<td valign="top">This is the best creative shot I have seen in this challenge.In my opinion it should have ribboned. I am not sure how you managed to get 7 ''2'' though .. it might have pulled your overall score down.If I were you, I would have contacted them and asked the reason ... Sad, you can''t do that in DPC ...</td>', 'This is the best creative shot I have seen in this challenge.In my opinion it should have ribboned. I am not sure how you managed to get 7 ''2'' though .. it might have pulled your overall score down.If I were you, I would have contacted them and asked the reason ... Sad, you can''t do that in DPC ...', '2009-02-18 13:13:26.000000', NULL, 0),
(5263092, 764020, 50695, '<td valign="top">Lovely.</td>', 'Lovely.', '2009-02-18 13:16:32.000000', NULL, 0),
(5263094, 764020, 50695, '<td valign="top">Wow, 4.5. I really wonder why I''m here. This makes me glad my shirt is grey.</td>', 'Wow, 4.5. I really wonder why I''m here. This makes me glad my shirt is grey.', '2009-02-18 13:17:03.000000', NULL, 0),
(5263141, 764162, 52549, '<td valign="top">I love the dark colors, it''s a beautiful image. Congrats on winning the blue, Brad.</td>', 'I love the dark colors, it''s a beautiful image. Congrats on winning the blue, Brad.', '2009-02-18 13:31:03.000000', NULL, 0),
